import{_ as t,o as a,c as r,ao as n}from"./chunks/framework.CK3rJ2mo.js";const m=JSON.parse('{"title":"The library of formulations","description":"","frontmatter":{},"headers":[],"relativePath":"studio/library.md","filePath":"studio/library.md","lastUpdated":null}'),i={name:"studio/library.md"};function h(l,e,s,d,o,f){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="studio-library" tabindex="-1">The library of formulations <a class="header-anchor" href="#studio-library" aria-label="Permalink to &quot;The library of formulations {#studio-library}&quot;">​</a></h1><p>The <em>Start</em> tab of the studio offers formulations published in papers, each loaded with one click: every tab is then filled, and the calculation can be run at once, changed, and saved under a name of your own. Nothing is downloaded: the formulations ship with the studio, and the compositions they use are those ChemistryLab holds, with their sources, in its material templates.</p><p>Only formulations published in a paper are offered. Where an entry takes a proportion from its paper (a replacement, a water-to-binder ratio), the tests of the studio check it against the data ChemistryLab holds for that paper. The degrees of reaction are illustrative unless the entry says otherwise: set them for the age you are interested in, or let rate laws decide them.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Formulation</th><th style="text-align:right;">What it computes</th><th style="text-align:right;">Sources</th></tr></thead><tbody><tr><td style="text-align:right;">CEM I 52.5 N paste</td><td style="text-align:right;">one equilibrium at 28 days, w/b 0.5</td><td style="text-align:right;">(<a href="/ChemistryLab.jl/v0.42/references#Gruyaert2010">Gruyaert <em>et al.</em>, 2010</a>), (<a href="/ChemistryLab.jl/v0.42/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr><tr><td style="text-align:right;">Portland cement paste, RILEM round robin</td><td style="text-align:right;">one equilibrium; its volumes are unknown, three minor oxides having no sourced density</td><td style="text-align:right;">(<a href="/ChemistryLab.jl/v0.42/references#Durdzinski2017">Durdziński <em>et al.</em>, 2017</a>), (<a href="/ChemistryLab.jl/v0.42/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr><tr><td style="text-align:right;">Portland cement with 40 % slag, RILEM round robin</td><td style="text-align:right;">one equilibrium of the paste PC-S1, w/b 0.4</td><td style="text-align:right;">(<a href="/ChemistryLab.jl/v0.42/references#Durdzinski2017">Durdziński <em>et al.</em>, 2017</a>), (<a href="/ChemistryLab.jl/v0.42/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr><tr><td style="text-align:right;">Portland cement with 30 % siliceous fly ash, RILEM round robin</td><td style="text-align:right;">one equilibrium of the paste PC-SFA, w/b 0.4</td><td style="text-align:right;">(<a href="/ChemistryLab.jl/v0.42/references#Durdzinski2017">Durdziński <em>et al.</em>, 2017</a>), (<a href="/ChemistryLab.jl/v0.42/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr><tr><td style="text-align:right;">Portland cement with 30 % siliceous fly ash in time, by rate laws</td><td style="text-align:right;">a kinetic run over 90 days, the clinker phases by the law of <a href="/ChemistryLab.jl/v0.42/references#ParrottKilloh1984">Parrott and Killoh (1984)</a>, the glass of the fly ash by the law of <a href="/ChemistryLab.jl/v0.42/references#Waller1999">Waller (1999)</a> with the set of <a href="/ChemistryLab.jl/v0.42/references#Lavergne2018">Lavergne <em>et al.</em> (2018)</a></td><td style="text-align:right;">(<a href="/ChemistryLab.jl/v0.42/references#Durdzinski2017">Durdziński <em>et al.</em>, 2017</a>), (<a href="/ChemistryLab.jl/v0.42/references#Lavergne2018">Lavergne <em>et al.</em>, 2018</a>), (<a href="/ChemistryLab.jl/v0.42/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr><tr><td style="text-align:right;">Slag cements: the replacement of a CEM I 52.5 N by slag</td><td style="text-align:right;">a path along the slag-to-binder ratios of the paper, 0 to 0.85</td><td style="text-align:right;">(<a href="/ChemistryLab.jl/v0.42/references#Gruyaert2010">Gruyaert <em>et al.</em>, 2010</a>), (<a href="/ChemistryLab.jl/v0.42/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr><tr><td style="text-align:right;">Hydration of a CEM I 52.5 N in time, by rate laws</td><td style="text-align:right;">a kinetic run over 28 days, the clinker phases by the law of <a href="/ChemistryLab.jl/v0.42/references#ParrottKilloh1984">Parrott and Killoh (1984)</a> with the parameters of <a href="/ChemistryLab.jl/v0.42/references#Lavergne2018">Lavergne <em>et al.</em> (2018)</a></td><td style="text-align:right;">(<a href="/ChemistryLab.jl/v0.42/references#Gruyaert2010">Gruyaert <em>et al.</em>, 2010</a>), (<a href="/ChemistryLab.jl/v0.42/references#Lavergne2018">Lavergne <em>et al.</em>, 2018</a>), (<a href="/ChemistryLab.jl/v0.42/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr><tr><td style="text-align:right;">CEM I 52.5 N of Lavergne et al. (2018) hydrating at w/b 0.50</td><td style="text-align:right;">a kinetic run over 28 days of the cement of <a href="/ChemistryLab.jl/v0.42/references#Lavergne2018">Lavergne <em>et al.</em> (2018)</a>, from the Bogue composition of its clinker, the clinker phases by the law of <a href="/ChemistryLab.jl/v0.42/references#ParrottKilloh1984">Parrott and Killoh (1984)</a></td><td style="text-align:right;">(<a href="/ChemistryLab.jl/v0.42/references#Lavergne2018">Lavergne <em>et al.</em>, 2018</a>), (<a href="/ChemistryLab.jl/v0.42/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr><tr><td style="text-align:right;">CEM I 52.5 N of Lavergne et al. (2018) hydrating at w/b 0.32</td><td style="text-align:right;">the same run at the lower water-to-binder ratio of their mortars, where the water left caps the hydration</td><td style="text-align:right;">(<a href="/ChemistryLab.jl/v0.42/references#Lavergne2018">Lavergne <em>et al.</em>, 2018</a>), (<a href="/ChemistryLab.jl/v0.42/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr><tr><td style="text-align:right;">CEM I 52.5 N of Lavergne et al. (2018) in a semi-adiabatic cell</td><td style="text-align:right;">their mortar C100 in their cell over 3.5 days: the cement and the water of its paste, the heat capacity of the vessel, the sand and the water it absorbs, and the loss of their calibration, linear and quadratic</td><td style="text-align:right;">(<a href="/ChemistryLab.jl/v0.42/references#Lavergne2018">Lavergne <em>et al.</em>, 2018</a>), (<a href="/ChemistryLab.jl/v0.42/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr><tr><td style="text-align:right;">Carbonation of a CEM I 52.5 N paste</td><td style="text-align:right;">a path of CO₂ added, up to 1 mol per 100 g of binder</td><td style="text-align:right;">(<a href="/ChemistryLab.jl/v0.42/references#Gruyaert2010">Gruyaert <em>et al.</em>, 2010</a>), (<a href="/ChemistryLab.jl/v0.42/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr><tr><td style="text-align:right;">Chloride binding by a CEM I 52.5 N paste, with the surface of its C-S-H</td><td style="text-align:right;">a path of NaCl added, up to 0.02 mol per 100 g of binder, with Friedel&#39;s and Kuzel&#39;s salts and the sites of <a href="/ChemistryLab.jl/v0.42/references#Guo2018">Guo <em>et al.</em> (2018)</a> on the C-S-H at each point</td><td style="text-align:right;">(<a href="/ChemistryLab.jl/v0.42/references#Gruyaert2010">Gruyaert <em>et al.</em>, 2010</a>), (<a href="/ChemistryLab.jl/v0.42/references#Guo2018">Guo <em>et al.</em>, 2018</a>), (<a href="/ChemistryLab.jl/v0.42/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr><tr><td style="text-align:right;">Leaching of a CEM I 52.5 N paste by pure water</td><td style="text-align:right;">twelve renewals of the pore solution by 5 kg of water</td><td style="text-align:right;">(<a href="/ChemistryLab.jl/v0.42/references#Gruyaert2010">Gruyaert <em>et al.</em>, 2010</a>), (<a href="/ChemistryLab.jl/v0.42/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld, 2006</a>)</td></tr></tbody></table><p>The phases of every entry are those <a href="/ChemistryLab.jl/v0.42/references#LothenbachWinnefeld2006">Lothenbach and Winnefeld (2006)</a> list for a Portland paste, in the thermodynamic database Cemdata18 (<a href="/ChemistryLab.jl/v0.42/references#Lothenbach2019">Lothenbach <em>et al.</em>, 2019</a>).</p>',5)])])}const c=t(i,[["render",h]]);export{m as __pageData,c as default};
